// ==========================================================
// utils/battle/data.js
// Read access to battleData.json (Gen 5, generated by
// tools/generate-battle-data.mjs).
// ==========================================================

import fs from "fs";

const data = JSON.parse(fs.readFileSync(new URL("../../battleData.json", import.meta.url), "utf8"));

// pokemonData.json stores PokeAPI type ids.
export const TYPE_ID_TO_NAME = {
  1: "Normal", 2: "Fighting", 3: "Flying", 4: "Poison", 5: "Ground", 6: "Rock",
  7: "Bug", 8: "Ghost", 9: "Steel", 10: "Fire", 11: "Water", 12: "Grass",
  13: "Electric", 14: "Psychic", 15: "Ice", 16: "Dragon", 17: "Dark",
};

export const getSpecies = (id) => data.species[id];
export const getMove = (moveId) => data.moves[moveId];

export function effectiveness(moveType, defenderTypes) {
  return defenderTypes.reduce((m, t) => m * (data.typeChart[moveType]?.[t] ?? 1), 1);
}

export const fallbackMoveFor = (types) => data.fallbackByType[types[0]];
